@app.get("/reports",response_class=HTMLResponse)
def reports(request:Request):
    g=guard(request)
    if g:return g
    pl=q("""SELECT COALESCE(SUM(CASE WHEN txn_type='income' THEN amount ELSE 0 END),0) revenue,
    COALESCE(SUM(CASE WHEN txn_type='expense' THEN amount ELSE 0 END),0) expenses FROM transactions""",one=True)
    assets=sum(Decimal(str(r["balance"])) for r in q("SELECT balance FROM accounts WHERE account_type='Asset'"))
    liabilities=sum(Decimal(str(r["balance"])) for r in q("SELECT balance FROM accounts WHERE account_type='Liability'"))
    equity=sum(Decimal(str(r["balance"])) for r in q("SELECT balance FROM accounts WHERE account_type='Equity'"))
    salesvat=q("SELECT COALESCE(SUM(tax),0) v FROM invoices",one=True)["v"]
    expvat=q("SELECT COALESCE(SUM(tax),0) v FROM expenses",one=True)["v"]
    netvat=Decimal(str(salesvat))-Decimal(str(expvat))
    body=f"""<div class='grid'><div class='card'><h3>Profit & Loss</h3><p>Revenue: <b>{money(pl['revenue'])}</b></p><p>Expenses: <b>{money(pl['expenses'])}</b></p><p>Net profit: <b>{money(Decimal(str(pl['revenue']))-Decimal(str(pl['expenses'])))}</b></p></div>
    <div class='card'><h3>Balance Sheet Snapshot</h3><p>Assets: <b>{money(assets)}</b></p><p>Liabilities: <b>{money(liabilities)}</b></p><p>Equity: <b>{money(equity)}</b></p></div>
    <div class='card'><h3>VAT Summary</h3><p>Output VAT: <b>{money(salesvat)}</b></p><p>Input VAT: <b>{money(expvat)}</b></p><p>Net VAT: <b>{money(netvat)}</b></p></div>
    <div class='card'><h3>Exports</h3><p><a class='btn' href='/export/transactions.csv'>Transactions CSV</a></p><p><a class='btn' href='/export/invoices.csv'>Invoices CSV</a></p></div></div>"""
    return page(request,"Reports",body)

