@app.get("/export/{kind}.csv")
def export_csv(request:Request,kind:str):
    if not user(request):return RedirectResponse("/login",303)
    if kind=="transactions":
        rows=q("SELECT txn_date,reference,description,category,txn_type,amount,tax,account_code FROM transactions ORDER BY id")
    elif kind=="invoices":
        rows=q("SELECT invoice_no,customer_name,issue_date,due_date,status,subtotal,tax,total,paid FROM invoices ORDER BY id")
    else:
        return RedirectResponse("/reports",303)
    out=StringIO()
    if rows:
        w=csv.DictWriter(out,fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows([dict(r) for r in rows])
    return StreamingResponse(iter([out.getvalue()]),media_type="text/csv",headers={"Content-Disposition":f"attachment; filename={kind}.csv"})
